// Step 0: keep only what you send: photos / JPEG or PDF files, a caption text, or a tap on a "which module?" button
const ALLOWED_CHAT_ID = 'YOUR_TELEGRAM_CHAT_ID'; // <-- your Telegram chat id
const day = t => new Date(t * 1000).toLocaleDateString('sv-SE', { timeZone: 'Europe/Paris' }); // YYYY-MM-DD
const out = [];
for (const item of $input.all()) {
  const cq = item.json.callback_query;
  const m = item.json.message || cq?.message;
  if (!m) continue;
  if (String(m.chat.id) !== ALLOWED_CHAT_ID) {
    throw new Error('Unknown chat ' + m.chat.id + '. If this is you, set ALLOWED_CHAT_ID = "' + m.chat.id + '" in the Normalize node.');
  }
  if (cq) {
    // button tap: the options are written in the question message itself ("Type: TD", "1 → Modélisation")
    const type = (m.text?.match(/^Type: (.+)$/m) || [])[1];
    const pick = (m.text?.match(new RegExp('^' + cq.data + ' → (.+)$', 'm')) || [])[1];
    if (type && pick) out.push({ json: { group_id: '', file_id: '', caption: pick.trim(), type: type.trim(), confirmed: true, msg_id: m.message_id, chat_id: String(m.chat.id), sent_date: day(m.date) } });
    continue; // "I'll type it" button: nothing to do, wait for your text
  }
  let fileId = null;
  if (m.photo?.length) fileId = m.photo[m.photo.length - 1].file_id; // largest size
  else if (['image/jpeg', 'application/pdf'].includes(m.document?.mime_type)) fileId = m.document.file_id;
  if (!fileId) {
    // a text message right after the files = the module title (+ type)
    if (m.text && !m.text.startsWith('/')) out.push({ json: { group_id: '', file_id: '', caption: m.text.trim(), msg_id: m.message_id, chat_id: String(m.chat.id), sent_date: day(m.date) } });
    continue; // PNG sent as *file* is ignored (send it as photo)
  }
  out.push({ json: {
    group_id: m.media_group_id || 'single_' + m.message_id,
    file_id: fileId,
    caption: (m.caption || '').trim(),
    msg_id: m.message_id,
    chat_id: String(m.chat.id),
    sent_date: day(m.date),
  } });
}
return out;

// Step 02: build the Notion requests from dms-worker's answer
const p = $('Prepare job').first().json;
const r = $('Process files').first().json;
// worker v2 answers with lists (a too-big PDF is split into parts); v1 answered with single ids
const batchIds = r.batch_upload_ids || [r.batch_upload_id];
const mergedIds = r.merged_upload_ids || [r.merged_upload_id];
const mergedNames = r.merged_filenames || [r.merged_filename];
const parts = r.parts || 1;
const totalPages = p.prevPages + r.new_pages;
const note = (r.merged ? 'merged' : (r.had_old ? 'new part (5 MB limit)' : 'first batch')) + (parts > 1 ? ' · split in ' + parts + ' parts (5 MB limit)' : '');
const properties = {
  'Merged PDF': { files: mergedIds.map((id, i) => ({ type: 'file_upload', file_upload: { id }, name: mergedNames[i] })) },
  Pages: { number: totalPages },
  Batches: { number: p.batches },
  'Last update': { date: { start: p.sentDate } },
  Type: { select: { name: p.type } },
};
const log = [
  { object: 'block', type: 'heading_3', heading_3: { rich_text: [
    { type: 'mention', mention: { date: { start: p.sentDate } } },
    { type: 'text', text: { content: ' · « ' + p.caption + ' »' }, annotations: { bold: true } },
    { type: 'text', text: { content: ' · +' + r.new_pages + ' page(s) · ' + r.batch_mb + ' MB · ' + note }, annotations: { color: 'gray' } },
  ] } },
  ...batchIds.map(id => ({ object: 'block', type: 'pdf', pdf: { type: 'file_upload', file_upload: { id } } })),
];
const createBody = {
  parent: { database_id: 'YOUR_NOTION_DATABASE_ID' },
  icon: { type: 'emoji', emoji: '📄' },
  properties: { Module: { title: [{ text: { content: p.module } }] }, ...properties },
  children: [
    { object: 'block', type: 'heading_2', heading_2: { rich_text: [{ text: { content: 'Upload log' } }] } },
    { object: 'block', type: 'divider', divider: {} },
    ...log,
  ],
};
return [{ json: {
  exists: !!p.pageId,
  pageId: p.pageId,
  createBody: JSON.stringify(createBody),
  updateBody: JSON.stringify({ properties }),
  appendBody: JSON.stringify({ children: log }),
  reply: (p.pageId ? '✅ ' : '🆕 ') + p.module + ' · ' + p.type + '\n+' + r.new_pages + ' page(s) · ' + p.sentDate + '\nTotal: ' + totalPages + ' pages · ' + p.batches + ' batch(es) · ' + note + (r.cropped ? '\n📐 ' + r.cropped + ' photo(s) cropped to the sheet' : '') + (r.rotated ? '\n↻ ' + r.rotated + ' page(s) turned upright' : ''),
} }];

// Step 0b: module + type. A button tap is trusted as is; a new or unsure module goes back to you as a question
const cap = $('Normalize').first().json;
const norm = s => (s || '').normalize('NFKD').replace(/[\u0300-\u036f]/g, '').trim().toLowerCase().replace(/\s+/g, ' ');
const title = p => (p.properties.Module?.title || []).map(t => t.plain_text).join('');
const modules = [...new Set(($('Find module').first().json.results || []).map(title).filter(Boolean))];
const known = s => modules.find(m => norm(m) === norm(s)) || ''; // also drops names Gemini made up

if (cap.confirmed) return [{ json: { module: known(cap.caption) || cap.caption, type: cap.type, confident: true } }];

const g = JSON.parse($('Gemini classify').first().json.candidates[0].content.parts[0].text);
const existing = known(g.existing);
const fresh = g.module.trim();
const confident = !!existing && (g.confident || norm(existing) === norm(fresh));
const opts = existing ? [existing, fresh] : [fresh]; // new modules always need one tap, so typos never create duplicates
return [{ json: {
  module: existing || fresh, type: g.type, confident,
  question: (existing ? '🤔 Not sure where to file' : '🆕 New module?') + ' « ' + cap.caption + ' »\nType: ' + g.type + '\n'
    + opts.map((o, k) => (k + 1) + ' → ' + o).join('\n') + '\n\nTap a button, or type the right name.',
  b1: (existing ? '📂 ' : '🆕 ') + opts[0],
  b2: existing ? '🆕 ' + fresh : "✏️ I'll type it",
} }];

// Step 01: everything dms-worker needs, as JSON only: file bytes never pass through n8n (that crashed its heap)
const cap = $('Normalize').first().json;
const d = $('Decide').first().json;
const norm = s => (s || '').normalize('NFKC').trim().toLowerCase().replace(/\s+/g, ' ');
const title = p => (p.properties.Module?.title || []).map(t => t.plain_text).join('');
const page = ($('Find module').first().json.results || []).find(p => norm(title(p)) === norm(d.module) && (p.properties.Type?.select?.name || 'Cours') === d.type); // rows without a type count as Cours
const rows = $input.all().map(i => i.json).filter(r => r.file_id).sort((a, b) => Number(a.msg_id) - Number(b.msg_id));
return [{ json: {
  module: page ? title(page) : d.module,
  type: d.type,
  pageId: page?.id || null,
  sentDate: cap.sent_date,
  caption: cap.caption,
  lastMsgId: Math.max(...rows.map(r => Number(r.msg_id))),
  files: rows.length,
  prevPages: page?.properties.Pages?.number || 0,
  batches: (page?.properties.Batches?.number || 0) + 1,
  job: {
    file_ids: rows.map(r => r.file_id),
    slug: (d.module + ' ' + d.type).normalize('NFKD').replace(/[\u0300-\u036f]/g, '').replace(/[^\w]+/g, '_').replace(/^_|_$/g, '') || 'module',
    date: cap.sent_date,
    old_url: page?.properties['Merged PDF']?.files?.at(-1)?.file?.url || null,
  },
} }];
